zones = {}
for uri, row in cat.items():
    # uri like ...#Zone_F1_Z01.Zone_Air_Temperature_Sensor
    base, _, cls = uri.rpartition('.')
    zname = base.split('#')[-1]
    if cls == 'Zone_Air_Temperature_Sensor':
        zones.setdefault(zname, {})['temp'] = row['timeseries_id']
    elif cls == 'Zone_Air_Cooling_Temperature_Setpoint':
        zones.setdefault(zname, {})['cool'] = row['timeseries_id']

print("All zones:")
